"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5007],{71054:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CannonServer","desc":"Authority for the manned cannon (Perk Spec 5). Discovers placed cannons in\\nworkspace.PlacedObjects (by the PlaceableName attribute), validates mount/fire\\nrequests, and simulates an authoritative explosive arc shell via a FastCast2\\ncast with a gravity Acceleration (the rocket pattern from WeaponServer). Damage\\nis scaled by the CannonDamage party perk and applied through CombatService.ApplyAOE.\\nHeat is tracked per cannon and published as Heat/Overheated attributes on the\\nplaced Model (no extra packet). Client aim is never trusted for damage.\\n\\nSmart Cannon (party shop perk): a cannon with no live occupant for\\n`AutoLoaderIdleTime` fires at the nearest visible enemy at `AutoLoaderRate` \xd7\\nthe manned rate, credited to the perk holder.","realm":["Server"],"source":{"line":18,"path":"src/ServerScriptService/CannonServer.server.luau"}}')}}]);